  },
  "attack_progression": [
    {
      "step": 1,
      "tactic": "Discovery — WMI Burst Query Reconnaissance",
      "technique": "T1082",
      "what_happened": "At 09:12:03 CEST, Wazuh rule 92220 fired on WIN-SRV-108 (agent 041, 10.108.57.184): WMI burst query recon — more than 5 distinct WQL queries issued within a 10-second window from a single process. ETW WMI-Activity telemetry captured rapid-fire queries against root\\cimv2 and root\\SecurityCenter2: Win32_ComputerSystem (OS and domain info), Win32_LogonSession (active sessions), Win32_GroupUser filtered on Administrators (local admin group members), AntiVirusProduct (AV products installed). The process issuing the queries is powershell.exe running as NT AUTHORITY\\SYSTEM. The burst pattern — more than 5 distinct WQL namespace targets within 10 seconds from the same PID — is the key differentiator from legitimate SCCM inventory which is paced and targets hardware classes only.",
      "chain_reason": "Wazuh rule 92220 'WMI burst query recon (>5 WQL queries in <10s)' [T1082] triggered by ETW WMI-Activity correlation: single process (powershell.exe, PID 4128) issued 6 distinct WQL statements across root\\cimv2 + root\\SecurityCenter2 in a 9-second window. Legitimate ccmexec.exe (SCCM) inventory queries are paced at >30 s between classes and never target LogonSession or GroupUser.",
      "first_seen": "2027-07-14T09:12:03+0200"
    },
    {
      "step": 2,
      "tactic": "Discovery — Win32_Product MSI Repair Audit Smoke",
      "technique": "T1047",
      "what_happened": "At 09:14:31 CEST (148 seconds after step 1), rule 92221 fired: Win32_Product enumeration detected. Querying Win32_Product via WMI is known to trigger Windows Installer to validate and repair every installed MSI package, generating excessive disk I/O and Windows Event 11707/11724 (install/repair) entries. This is a well-documented attacker side-effect used to enumerate installed software for target profiling (identifying EDR products, patching gaps, admin tooling). The same PID 4128 (powershell.exe as SYSTEM) issued SELECT Name, Version, Vendor FROM Win32_Product.",
      "chain_reason": "Wazuh rule 92221 'Win32_Product query — MSI repair audit smoke' [T1047] correlated with Windows Installer repair event burst (Event 11707 x N) within 60 s of the WMI query. The repair side-effect pattern is a documented forensic artifact of Win32_Product enumeration used by Cobalt Strike and similar post-exploitation frameworks.",
      "first_seen": "2027-07-14T09:14:31+0200"
    },
    {
      "step": 3,
      "tactic": "Discovery — WMI LogonSession and GroupUser Credential Hunting",
      "technique": "T1087",
      "what_happened": "At 09:17:55 CEST, rule 92222 fired: WMI LogonSession + GroupUser enumeration classified as credential hunt (T1087 Account Discovery). The combination of SELECT * FROM Win32_LogonSession (reveals which domain accounts have active sessions on the host) and SELECT * FROM Win32_GroupUser WHERE GroupComponent LIKE '%Administrators%' (reveals local admin group membership) is the standard pre-lateral-movement intelligence-gathering pattern. Attackers use LogonSession results to identify high-value domain admin accounts currently logged in, then target those accounts for token impersonation or credential theft.",
      "chain_reason": "Wazuh rule 92222 'WMI LogonSession + GroupUser enum (credential hunt)' [T1087] triggered by the co-occurrence of both class queries from the same PID within the burst window. LogonSession + GroupUser together serve no legitimate automated-inventory purpose; the combination is a near-exclusive indicator of attacker-tooling host profiling.",
      "first_seen": "2027-07-14T09:17:55+0200"
    }
  ],
  "process_context": {
    "image": "C:\\Windows\\System32\\WindowsPowerShell\\v1.0\\powershell.exe",
    "pid": 4128,
    "user": "NT AUTHORITY\\SYSTEM",
    "parent_image": "C:\\Windows\\System32\\wmiprvse.exe",
    "note": "powershell.exe spawned under wmiprvse.exe is a classic WMI lateral-movement or persistence execution pattern — wmiprvse.exe is the WMI provider host and should not normally spawn interactive PowerShell children"
  },
  "mitre": ["T1047", "T1082", "T1087"]
}
